// Works out what Mahek wants and for which customer / order – without her typing a number:
// 1. a button she tapped (ids like a:pa:919800000000, a:fin:RC-1007-K3F9),
// 2. a number or order ID she typed,
// 3. the alert she swipe-replied to,
// 4. the order she is finalizing, or the customer she opened last (within 6 hours).
const inp = $('Admin In').first().json;
const m = inp.msg || {};
let st = {};
try { st = JSON.parse($('Admin State').first().json.value || '{}') || {}; } catch (e) { st = {}; }
const ctx = $('Alert Context').first().json || {};
const text = String(m.text || '').trim();
const low = text.toLowerCase().replace(/[*_~]/g, '');
const rid = String(m.reply_id || '');
const pending = st.pending && st.pending.order_id ? st.pending : null;

let cmd = '', phone = '', order = '', arg = null;
const asPhone = (s) => { const d = String(s || '').replace(/\D/g, ''); return d.length === 10 ? '91' + d : d.length === 12 && d.startsWith('91') ? d : ''; };

const b = rid.match(/^a:([a-z]+):?(.*)$/);
if (b) {
  cmd = b[1];
  const v = b[2] || '';
  if (/^RC-/i.test(v)) order = v.toUpperCase();
  else if (/^p:/.test(v)) phone = asPhone(v.slice(2));
  else if (v) phone = asPhone(v);
  if (cmd === 'finp') cmd = 'fin';
  if (cmd === 'cust') cmd = 'st';
} else {
  const typedPhone = asPhone((text.match(/\+?\d[\d\s-]{8,}\d/) || [''])[0]);
  const typedOrder = (text.match(/\bRC-\d{4}-[A-Z0-9]{4}\b/i) || [''])[0].toUpperCase();
  if (typedPhone) phone = typedPhone;
  if (typedOrder) order = typedOrder;
  const w = low.split(/[\s:,.!?-]+/).filter(Boolean)[0] || '';
  const WORDS = {
    pause: 'pa', stop: 'pa', band: 'pa', hold: 'pa', quiet: 'pa',
    resume: 're', unpause: 're', chalu: 're', continue: 're', restart: 're',
    status: 'st', info: 'st', details: 'st', detail: 'st', check: 'st',
    final: 'fin', finalize: 'fin', finalise: 'fin', finalised: 'fin', finalized: 'fin', confirm: 'fin', bill: 'fin', pdf: 'fin',
    menu: 'menu', hi: 'menu', hii: 'menu', hello: 'menu', hey: 'menu', list: 'menu', customers: 'menu', customer: 'menu', help: 'menu', start: 'menu',
    orders: 'orders', order: 'orders', pending: 'orders', open: 'orders',
    sheet: 'sheet', sheets: 'sheet', leads: 'sheet', excel: 'sheet',
    page: 'page', website: 'page', site: 'page', web: 'page', portal: 'page', login: 'page', edit: 'page',
    cancel: 'cxl', send: 'send', free: 'free', shipping: 'ship',
  };
  // while finalizing: "350" / "₹350" / "rs 350" = shipping, "TESLA-707 3" = change an item, "free" = no shipping
  const amount = text.match(/^(?:₹|rs\.?|inr)?\s*(\d[\d,]*(?:\.\d{1,2})?)\s*(?:₹|rs\.?|\/-|rupees?)?$/i);
  const item = text.match(/^([A-Za-z]{0,6}[\s-]?\d{1,4}[A-Za-z0-9-]*)\s*[:=x×-]?\s*(\d{1,3})\s*(?:pkts?|packets?|box(?:es)?|pcs)?$/i);
  if (pending && amount && !typedPhone) { cmd = 'shipamt'; arg = parseFloat(amount[1].replace(/,/g, '')); order = pending.order_id; }
  else if (pending && item && !typedPhone) { cmd = 'item'; arg = { code: item[1], n: parseInt(item[2], 10) }; order = pending.order_id; }
  else if (WORDS[w]) cmd = WORDS[w];
  else if (/^(free|no) ?shipping$/.test(low)) cmd = 'free';
  else if (typedPhone || typedOrder) cmd = typedOrder ? 'fin' : 'st';
  else cmd = 'unknown';
  if (cmd === 'orders' && (typedPhone || typedOrder)) cmd = typedOrder ? 'fin' : 'st';
}

// commands about the order being finalized
if (['shipamt', 'item', 'free', 'send', 'cxl', 'ship'].includes(cmd) && !order && pending) order = pending.order_id;
// no number typed: the alert she replied to, else the customer she last opened
let via = phone ? 'typed' : order ? 'order' : '';
if (!phone && !order && ['pa', 're', 'st', 'fin'].includes(cmd)) {
  if (ctx.phone) { phone = ctx.phone; if (cmd === 'fin' && ctx.order_id) order = ctx.order_id; via = 'reply'; }
  else if (st.focus && Date.now() - (Number(st.focus_ms) || 0) < 6 * 3600 * 1000) { phone = st.focus; via = 'last'; }
}
return [{ json: { cmd, phone, order, arg, via, state: st, pending, text, reply_id: rid, phone_number_id: inp.phone_number_id || m.phone_number_id || '' } }];

// Carries out Mahek's command and writes her replies (WhatsApp buttons and lists, so she rarely has to type).
// Finalizing an order: tap Finalize -> reply with the shipping cost (and optionally change items) -> Send to customer
// -> the "RC - Order Confirmation" workflow makes the PDF and sends it to the customer, with a copy to Mahek.
const MAHEK = '919112296139';
const SHEET = 'https://docs.google.com/spreadsheets/d/1W4jmnP3XUVXk7EimIOOjTx4GcfaqHiUAXnaM1bsGiHE/edit';
const ORDERS_PAGE = 'https://rajcreation.info/orders/'; // Mahek's order page (workflow "RC - Order Portal")
const ZONE = 'Asia/Kolkata', FMT = 'yyyy-MM-dd HH:mm:ss';
const u = $('Understand').first().json;
const nowDt = $now.setZone(ZONE);
const now = nowDt.toFormat(FMT);
const st = Object.assign({}, u.state || {});
st.last_in_ms = Date.now(); // Mahek's 24-hour window is open: alerts can go as normal messages with buttons
const orders = $('Find Orders').all().map((i) => i.json).filter((o) => o && o.order_id).sort((a, b) => (Number(b.created_ms) || 0) - (Number(a.created_ms) || 0));
let cust = $('Find Customer').first().json || {};
if (!cust.phone) cust = null;
const recent = $('Recent Customers').all().map((i) => i.json).filter((r) => r && r.phone && r.phone !== MAHEK);
const openList = $('Open Orders').all().map((i) => i.json).filter((o) => o && o.order_id);

// ---- helpers ----
const clip = (s, n) => { const v = String(s === undefined || s === null ? '' : s).replace(/\s+/g, ' ').trim(); return v.length > n ? v.slice(0, n - 1) + '…' : v; };
const inr2 = (n) => '₹' + Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: Number(n) % 1 ? 2 : 0, maximumFractionDigits: 2 });
const nice = (p) => '+' + String(p || '').replace(/^91(\d{5})(\d{5})$/, '91 $1 $2');
const itemsOf = (o) => { try { const a = typeof o.items === 'string' ? JSON.parse(o.items || '[]') : o.items; return Array.isArray(a) ? a : []; } catch (e) { return []; } };
const parseT = (s) => { if (!s) return null; const d = DateTime.fromFormat(String(s).trim(), FMT, { zone: ZONE }); return d.isValid ? d : null; };
const when = (s) => { const d = parseT(s); return d ? d.toFormat('dd MMM, hh:mm a') : (s || '-'); };
const norm = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const core = (s) => norm(s).replace(/^(RC|RJ|RAJ|RT|TESLA|T)(?=\d)/, '').replace(/(^|[A-Z])0+(?=\d)/g, '$1');
const LANGS = { hi: 'Hindi', gu: 'Gujarati', ta: 'Tamil', te: 'Telugu', en: 'English' };
const STEPS = { awaiting_language: 'choosing a language', awaiting_details: 'asked for shop name & city', awaiting_category: 'asked for business type', awaiting_order_value: 'asked for order value', rate_list_sent: 'rate list sent', escalated_to_sales: 'handed to sales', order_received: 'website order received' };
const custName = (c) => (c && (c.whatsapp_name || c.business_details)) || 'this customer';
const shopOf = (c, o) => (o && [o.shop, o.city].filter(Boolean).join(', ')) || (c && c.business_details) || '';
const isPaused = (c) => { const d = c && parseT(c.paused_until); return !!(d && d > nowDt); };
function totals(items, handling) {
  const it = Math.round(items.reduce((s, x) => s + (Number(x.amount) || 0), 0) * 100) / 100;
  const gst = Math.round((it + (Number(handling) || 0)) * 0.05 * 100) / 100;
  return { items_total: it, gst, total: Math.round((it + (Number(handling) || 0) + gst) * 100) / 100, packets: items.reduce((s, x) => s + (Number(x.packets) || 0), 0), dozens: items.reduce((s, x) => s + (Number(x.packets) || 0) * (Number(x.dz) || 0), 0) };
}
const lineFull = (x, i) => (i + 1) + '. ' + x.code + (x.desc ? ' (' + x.desc + ')' : '') + ' – ' + x.packets + ' ' + x.unit + ' × ' + x.dz + ' dz × ' + inr2(x.rate) + ' = ' + inr2(x.amount);
const lineShort = (x, i) => (i + 1) + '. ' + x.code + ' ×' + x.packets + ' ' + x.unit + ' = ' + inr2(x.amount);
function listFit(items, head, foot, max) {
  let list = items.map(lineFull);
  const fits = (l) => (head + l.join('\n') + foot).length <= max;
  if (!fits(list)) list = items.map(lineShort);
  if (!fits(list)) { let k = list.length; const more = (k) => '…and ' + (items.length - k) + ' more'; while (k > 1 && !fits(list.slice(0, k).concat(more(k)))) k--; list = list.slice(0, k).concat(more(k)); }
  return head + list.join('\n') + foot;
}

// ---- message builders ----
const base = (extra) => Object.assign({ messaging_product: 'whatsapp', recipient_type: 'individual', to: MAHEK }, extra);
const btn = (id, title) => ({ type: 'reply', reply: { id, title } });
const buttons = (body, bts, header, footer) => base({ type: 'interactive', interactive: Object.assign({ type: 'button', body: { text: body.slice(0, 1024) }, action: { buttons: bts.slice(0, 3) } },
  header ? { header: { type: 'text', text: clip(header, 60) } } : {}, footer ? { footer: { text: clip(footer, 60) } } : {}) });
const cta = (body, label, url, header) => base({ type: 'interactive', interactive: Object.assign({ type: 'cta_url', body: { text: body.slice(0, 1024) }, action: { name: 'cta_url', parameters: { display_text: label, url } } }, header ? { header: { type: 'text', text: clip(header, 60) } } : {}) });
const text = (body) => base({ type: 'text', text: { body: body.slice(0, 4096), preview_url: false } });
const list = (body, label, title, rows, header) => base({ type: 'interactive', interactive: Object.assign({ type: 'list', body: { text: body.slice(0, 1024) }, action: { button: label, sections: [{ title: clip(title, 24), rows: rows.slice(0, 10) }] } }, header ? { header: { type: 'text', text: clip(header, 60) } } : {}) });

const out = { messages: [], state: st, customer_update: null, order_update: null, confirm: null, focus: '' };
const say = (msg, meta) => out.messages.push({ payload: msg, phone: (meta && meta.phone) || '', order_id: (meta && meta.order_id) || '' });

// a button that opens the order page: change items, out of stock, replacements, tell the customer
const pageButton = () => say(cta('🧾 *Orders page* – check website orders, mark items out of stock or limited, suggest replacements, set shipping and send the update to the customer.\n\nLog in with the code the bot sends you here.', 'Open orders page', ORDERS_PAGE, 'Raj Creation orders'));

function statusCard(c) {
  const ords = orders.filter((o) => o.phone === c.phone);
  const last = ords[0];
  const open = ords.find((o) => o.status !== 'confirmed' && o.status !== 'cancelled');
  const lang = (String(c.stage || '').match(/^(hi|gu|ta|te|en):/) || [])[1] || 'en';
  const step = String(c.stage || '').replace(/^(hi|gu|ta|te|en):/, '').split('#')[0];
  const paused = isPaused(c);
  const body = '👤 *' + (c.whatsapp_name || 'Customer') + '* · ' + nice(c.phone) + '\n' +
    '🏪 ' + (shopOf(c, last) || 'shop not given yet') + '\n' +
    '🏷️ ' + (c.category || 'type not given yet') + ' · ' + LANGS[lang] + '\n' +
    '🤖 Bot: ' + (paused ? '⏸️ paused until ' + when(c.paused_until) : '▶️ replying') + '\n' +
    '📍 Step: ' + (STEPS[step] || step || 'new') + '\n' +
    (last ? '🧾 Last order: ' + last.order_id + ' · ' + inr2(last.total) + ' · ' + last.status + (last.confirmed_at ? ' (confirmed ' + when(last.confirmed_at) + ')' : '') + '\n' : '') +
    (ords.length > 1 ? '🗂️ ' + ords.length + ' orders in total\n' : '') +
    '💬 Last message: "' + clip(c.last_message || '-', 300) + '"\n' +
    '🕒 ' + when(c.last_in_at || c.updated_at) + '\n\n' +
    'Chat: https://wa.me/' + c.phone;
  const bts = [paused ? btn('a:re:' + c.phone, '▶️ Resume bot') : btn('a:pa:' + c.phone, '⏸️ Pause bot')];
  if (open || last) bts.push(btn('a:fin:' + (open || last).order_id, '✅ Finalize order'));
  bts.push(btn('a:sheet', '📊 Leads sheet'));
  say(buttons(body, bts, '📋 ' + (c.whatsapp_name || nice(c.phone))), { phone: c.phone, order_id: (open || last || {}).order_id });
  out.focus = c.phone;
}
function menu(note) {
  const rows = recent.slice(0, 10).map((r) => {
    const step = String(r.stage || '').replace(/^(hi|gu|ta|te|en):/, '').split('#')[0];
    return { id: 'a:cust:' + r.phone, title: clip(r.whatsapp_name || nice(r.phone), 24), description: clip([r.business_details, isPaused(r) ? '⏸️ paused' : '', STEPS[step] || step].filter(Boolean).join(' · '), 72) };
  });
  const body = (note ? note + '\n\n' : '') + 'Hi Mahek 👋 Tap *Customers* to open anyone who messaged recently – you can see their status, pause or resume the bot, and finalize their order.\n\n' +
    'You can also type:\n• *orders* – open website orders\n• *page* – the orders page on the website (edit orders)\n• *status 98XXXXXXXX* – any customer\n• *pause* / *resume* / *status* – for the customer you opened last\n\n' +
    'Tip: swipe-reply to any alert and type *pause*, *status* or *finalize* – no number needed.';
  if (rows.length) say(list(body, 'Customers', 'Recent customers', rows, 'Raj Creation bot'));
  else say(text(body));
  pageButton();
}
function finalizePrompt(p, o, note) {
  const t = totals(p.items, p.handling);
  const head = (note ? note + '\n\n' : '') + '*' + (shopOf(cust, o) || o.name || 'Customer') + '* · ' + (o.name || '') + ' · ' + nice(o.phone) + '\n\n';
  const foot = '\n\nItems ' + inr2(t.items_total) + (p.handling ? ' + handling ' + inr2(p.handling) : '') + ' + GST ' + inr2(t.gst) + '\n*Total ' + inr2(t.total) + '* + shipping\n\n' +
    '🚚 *Reply with the shipping cost* in ₹, e.g. *350*\n✏️ To change an item, reply with its code and packets, e.g. *' + ((p.items[0] || {}).code || 'TESLA-707') + ' 3* (0 removes it).';
  say(buttons(listFit(p.items, head, foot, 1024), [btn('a:free:' + o.order_id, '🚚 Free shipping'), btn('a:cxl:' + o.order_id, '❌ Cancel')], '✅ Finalize ' + o.order_id), { phone: o.phone, order_id: o.order_id });
}
function preview(p, o, note) {
  const t = totals(p.items, p.handling);
  const ship = Number(p.shipping) || 0;
  const head = (note ? note + '\n\n' : '') + '*' + (shopOf(cust, o) || o.name || 'Customer') + '* · ' + nice(o.phone) + '\n\n';
  const foot = '\n\nItems ' + inr2(t.items_total) + (p.handling ? ' + handling ' + inr2(p.handling) : '') + ' + GST ' + inr2(t.gst) + ' = ' + inr2(t.total) +
    '\n🚚 Shipping: ' + (ship ? inr2(ship) : 'free') + '\n💰 *Grand total ' + inr2(t.total + ship) + '*\n\n' +
    'Tap *Send to customer* to send the PDF confirmation to ' + (o.name || 'the customer') + ' – you get a copy too.';
  say(buttons(listFit(p.items, head, foot, 1024), [btn('a:send:' + o.order_id, '📄 Send to customer'), btn('a:ship:' + o.order_id, '🚚 Change shipping'), btn('a:cxl:' + o.order_id, '❌ Cancel')], '📄 Ready to send ' + o.order_id), { phone: o.phone, order_id: o.order_id });
}
function needCustomer(what) {
  menu('Which customer should I ' + what + '? Pick one below, type their number (e.g. *' + what + ' 98XXXXXXXX*), or swipe-reply to their alert.');
}

const cmd = u.cmd;
const findOrder = () => (u.order && orders.find((o) => o.order_id === u.order)) || orders.find((o) => o.phone === u.phone && o.status !== 'confirmed' && o.status !== 'cancelled') || orders.find((o) => o.phone === u.phone) || null;
const p = st.pending && st.pending.order_id ? st.pending : null;

if (cmd === 'menu' || cmd === 'help') {
  menu();
} else if (cmd === 'unknown') {
  menu(p ? 'I did not understand that. You are finalizing order *' + p.order_id + '*: reply with the shipping cost (e.g. *350*), or an item code and packets (e.g. *TESLA-707 3*).' : 'Sorry, I did not understand that.');
} else if (cmd === 'sheet') {
  say(cta('📊 *Leads & orders sheet*\n\n• *Sheet1* – every customer, their step and messages\n• *Orders* – every website order with items, totals, shipping and status', 'Open sheet', SHEET, 'Raj Creation sheet'));
} else if (cmd === 'orders') {
  const rows = openList.slice(0, 10).map((o) => ({ id: 'a:fin:' + o.order_id, title: o.order_id, description: clip([o.shop || o.name, o.city, inr2(o.total), o.status === 'updated' ? 'updated' : 'new', String(o.created_at || '').slice(5, 16)].filter(Boolean).join(' · '), 72) }));
  if (rows.length) say(list('🧾 *Open website orders* (not confirmed yet)\n\nTap one to finalize it: you will be asked for the shipping cost, then the customer gets a PDF confirmation.', 'Open orders', 'Open orders', rows, 'Website orders'));
  else say(text('✅ No open website orders – everything is confirmed.'));
  pageButton();
} else if (cmd === 'page') {
  pageButton();
} else if (['pa', 're', 'st'].includes(cmd)) {
  if (!u.phone) needCustomer(cmd === 'pa' ? 'pause' : cmd === 're' ? 'resume' : 'show');
  else if (!cust) say(text('No customer found with number ' + nice(u.phone) + '. Please check the number.'));
  else if (cmd === 'st') statusCard(cust);
  else {
    const pause = cmd === 'pa';
    const until = pause ? nowDt.plus({ days: 30 }).toFormat(FMT) : '';
    out.customer_update = { phone: cust.phone, paused_until: until };
    cust.paused_until = until;
    const who = '*' + custName(cust) + '* (' + nice(cust.phone) + ')';
    say(buttons(pause ? '⏸️ Bot paused for ' + who + '. It stays quiet for them until you tap *Resume bot* (or 30 days).' : '▶️ The bot is replying to ' + who + ' again.',
      [pause ? btn('a:re:' + cust.phone, '▶️ Resume bot') : btn('a:pa:' + cust.phone, '⏸️ Pause bot'), btn('a:st:' + cust.phone, '📋 Status')]), { phone: cust.phone });
    out.focus = cust.phone;
  }
} else if (cmd === 'fin') {
  const o = findOrder();
  if (!u.phone && !u.order) needCustomer('finalize');
  else if (!o) {
    say(text('No website order found for ' + (cust ? '*' + custName(cust) + '*' : nice(u.phone)) + '. Orders are created when the customer sends their cart from rajcreation.info.'));
    if (cust) statusCard(cust);
  } else {
    st.pending = { action: 'ship', order_id: o.order_id, phone: o.phone, items: itemsOf(o), handling: Number(o.handling) || 0, shipping: null, ms: Date.now() };
    out.focus = o.phone;
    const note = o.status === 'confirmed' ? 'ℹ️ This order was already confirmed on ' + when(o.confirmed_at) + '. Finalizing again sends a *revised* PDF.' : o.needs_sales ? '⚠️ Needs your call: cartons / mixed boxes and packets.' : '';
    finalizePrompt(st.pending, o, note);
  }
} else if (['shipamt', 'free', 'ship', 'item', 'send', 'cxl'].includes(cmd)) {
  const o = (p && orders.find((x) => x.order_id === p.order_id)) || null;
  if (!p || !o || (u.order && u.order !== p.order_id)) {
    // a button from an older finalize message: start that one again
    const o2 = u.order && orders.find((x) => x.order_id === u.order);
    if (o2 && cmd !== 'cxl') {
      st.pending = { action: 'ship', order_id: o2.order_id, phone: o2.phone, items: itemsOf(o2), handling: Number(o2.handling) || 0, shipping: null, ms: Date.now() };
      finalizePrompt(st.pending, o2, 'Let us start again for order ' + o2.order_id + '.');
    } else if (cmd === 'cxl') say(text('Nothing to cancel – no order is being finalized.'));
    else menu('No order is being finalized right now.');
  } else if (cmd === 'cxl') {
    st.pending = null;
    say(text('❌ Finalizing ' + o.order_id + ' cancelled. Nothing was sent to the customer.'));
  } else if (cmd === 'shipamt' || cmd === 'free') {
    if (cmd === 'shipamt' && !(u.arg >= 0 && u.arg < 100000)) say(text('Please reply with the shipping cost as a number, e.g. *350*.'));
    else { p.shipping = cmd === 'free' ? 0 : Math.round(u.arg * 100) / 100; p.action = 'confirm'; st.pending = p; preview(p, o); }
  } else if (cmd === 'ship') {
    p.action = 'ship'; p.shipping = null; st.pending = p; finalizePrompt(p, o);
  } else if (cmd === 'item') {
    const want = norm(u.arg.code), wantCore = core(u.arg.code);
    const i = p.items.findIndex((x) => norm(x.code) === want) >= 0 ? p.items.findIndex((x) => norm(x.code) === want) : p.items.findIndex((x) => core(x.code) === wantCore);
    if (i < 0) say(text('Item *' + u.arg.code + '* is not in order ' + o.order_id + '. Items: ' + p.items.map((x) => x.code).join(', ')));
    else {
      const x = p.items[i];
      let note;
      if (u.arg.n === 0) { p.items.splice(i, 1); note = '➖ Removed ' + x.code + '.'; }
      else { note = '🔁 ' + x.code + ': ' + x.packets + ' → ' + u.arg.n + ' ' + x.unit + '.'; x.packets = u.arg.n; x.amount = Math.round(x.packets * x.dz * x.rate * 100) / 100; }
      st.pending = p;
      if (!p.items.length) { st.pending = null; say(text('All items removed – finalizing cancelled. Nothing was sent.')); }
      else if (p.shipping === null || p.shipping === undefined) finalizePrompt(p, o, note);
      else preview(p, o, note);
    }
  } else if (cmd === 'send') {
    if (p.shipping === null || p.shipping === undefined) finalizePrompt(p, o, 'Please send the shipping cost first.');
    else {
      const t = totals(p.items, p.handling);
      const ship = Number(p.shipping) || 0;
      const lines = p.items.map(lineFull).join('\n');
      const changed = JSON.stringify(itemsOf(o).map((x) => [x.code, x.packets])) !== JSON.stringify(p.items.map((x) => [x.code, x.packets]));
      const upd = Object.assign({}, o, {
        items: JSON.stringify(p.items), lines_text: lines, packets: t.packets, dozens: t.dozens,
        items_total: t.items_total, handling: p.handling, gst: t.gst, total: t.total, shipping: ship, grand_total: Math.round((t.total + ship) * 100) / 100,
        status: 'confirmed', confirmed_at: now, updated_at: now, version: (Number(o.version) || 1) + (changed ? 1 : 0),
